'use client';

import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { 
  LayoutDashboard, 
  Building2, 
  Users, 
  Globe, 
  TrendingUp, 
  Settings 
} from 'lucide-react';

export default function Sidebar() {
  const pathname = usePathname();

  const menuGroups = [
    {
      title: 'หมวดภาพรวม & การเงิน',
      items: [
        { name: 'แดชบอร์ดหลัก', href: '/', icon: LayoutDashboard },
        { name: 'บัญชีธนาคาร & พื้นที่ส่วนตัว', href: '/personal', icon: Building2 },
      ],
    },
    {
      title: 'หมวดจัดการลูกหนี้ & คำขอกู้',
      items: [
        { 
          name: 'รายชื่อลูกหนี้ทั้งหมด', 
          href: '/customers', 
          icon: Users,
          subItems: [
            { name: 'ดอกลอย', href: '/customers?type=floating' },
            { name: 'จบต้นดอก', href: '/customers?type=fixed_term' },
            { name: 'ยอดค้างรอเครียร์', href: '/customers?type=fixed_balance' },
          ]
        },
        { name: 'หน้าบ้านสมาชิก (apply.html)', href: '/apply', icon: Globe },
      ],
    },
    {
      title: 'หมวดรายงาน & ตั้งค่า',
      items: [
        { name: 'รายงานผลประกอบการประจำเดือน', href: '/reports', icon: TrendingUp },
        { name: 'ตั้งค่าระบบหลังบ้าน', href: '/settings', icon: Settings },
      ],
    },
  ];

  return (
    <aside className="w-64 bg-slate-900 border-r border-slate-800 min-h-screen text-slate-300 flex flex-col justify-between shrink-0">
      <div>
        {/* Header Branding */}
        <div className="p-5 border-b border-slate-800 flex items-center space-x-3">
          <div className="p-2 bg-purple-600 rounded-lg text-white font-bold text-xl">
            S819
          </div>
          <div>
            <h1 className="font-bold text-white text-lg leading-tight">SUBLON819</h1>
            <p className="text-xs text-slate-400">Executive Portal v2.0</p>
          </div>
        </div>

        {/* Navigation Links */}
        <nav className="p-4 space-y-6">
          {menuGroups.map((group, idx) => (
            <div key={idx}>
              <h2 className="text-xs font-semibold text-slate-500 uppercase tracking-wider mb-2">
                {group.title}
              </h2>
              <div className="space-y-1">
                {group.items.map((item) => {
                  const Icon = item.icon;
                  const isActive = pathname === item.href;

                  return (
                    <div key={item.name}>
                      <Link
                        href={item.href}
                        className={`flex items-center space-x-3 px-3 py-2.5 rounded-lg text-sm font-medium transition-colors ${
                          isActive
                            ? 'bg-purple-600 text-white font-semibold'
                            : 'hover:bg-slate-800 hover:text-white text-slate-400'
                        }`}
                      >
                        <Icon className="w-5 h-5" />
                        <span>{item.name}</span>
                      </Link>

                      {/* Submenu Items */}
                      {item.subItems && (
                        <div className="ml-8 mt-1 space-y-1 border-l-2 border-slate-800 pl-3">
                          {item.subItems.map((sub) => (
                            <Link
                              key={sub.name}
                              href={sub.href}
                              className="block py-1 text-xs text-slate-400 hover:text-purple-400 transition-colors"
                            >
                              🔹 {sub.name}
                            </Link>
                          ))}
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            </div>
          ))}
        </nav>
      </div>

      <div className="p-4 border-t border-slate-800 text-xs text-slate-500 text-center">
        SUBLON819 System Online
      </div>
    </aside>
  );
}